QUAL={'R':REAL,'D':DES,'I':ILL}
entries=[];k=0
for line in RAW.strip().splitlines():
    f=line.split('|'); assert len(f)==12,(k,len(f),line[:40])
    sub,title,who,story,text,shot,light,style,q,m,p,desc=f
    subj=ALICE if who=='A' else KEN
    n=1049+k; gpt=(k%2==0)
    model='GPT Image 2' if gpt else 'Nano Banana Pro'
    parts=[f'【主題】{title}',f'【主角】{subj}',f'【動作構圖】{story}。']
    if text!='無': parts.append(f'【畫面文字】以下文字必須以繁體中文清晰正確呈現：{text}。')
    parts+= [f'【鏡頭運鏡】{shot}。',f'【光線色調】{light}。',f'【拍攝風格】{style}',f'【畫質要求】{QUAL[q]}',f'【注意事項】{NOTE}',f'【避免】{AVOID}','【比例】9:16 直式（--ar 9:16）']
    prompt='\n'.join(parts)
    entries.append({'slug':f'prompt-{n}','title':title,'originalTitle':title,'category':C,'subcategory':sub,'prompt':prompt,
      'description':desc+'（靈感來源：數位時代《ChatGPT Image 2.0 提示詞怎麼下？》，已改寫為 '+('Alice' if who=='A' else 'Ken')+' 版）',
      'image':f'/media/prompt-examples/example-{n}.jpg','model':model,'imageModel':'GPT Image 2.5' if gpt else 'Nano Banana 2','requiresReference':True,
      'source':'AK Wealth Global 原創提示詞','tags':[sub,model,style,'9:16',f'馬斯洛：{M[m]}',f'PESTLE：{P[p]}','實用設計','Alice' if who=='A' else 'Ken'],'maslow':M[m],'pestle':P[p],'_who':who})
    k+=1
from collections import Counter
assert len(entries)==50,len(entries)
assert not [t for t,c in Counter(e['title'] for e in entries).items() if c>1]
who={e['slug']:e.pop('_who') for e in entries}
json.dump(who,open(sys.argv[1].replace('.json','-who.json'),'w'),indent=1)
json.dump(entries,open(sys.argv[1],'w',encoding='utf8'),ensure_ascii=False,indent=2)
